package br.com.cuidaplus.api.service_request;
import br.com.cuidaplus.api.care_contract.*; import br.com.cuidaplus.api.common.BusinessException; import br.com.cuidaplus.api.notification.*; import br.com.cuidaplus.api.profile.*; import br.com.cuidaplus.api.service_request.dto.*; import br.com.cuidaplus.api.user.*; import java.time.*; import java.util.*; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Sort; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CaregiverServiceRequestService{private final ServiceRequestRepository requests;private final UserService users;private final CareContractRepository contracts;private final NotificationService notifications;private final ResponsibleProfileRepository responsibleProfiles;public CaregiverServiceRequestService(ServiceRequestRepository r,UserService u,CareContractRepository c,NotificationService n,ResponsibleProfileRepository rp){requests=r;users=u;contracts=c;notifications=n;responsibleProfiles=rp;}
 @Transactional public CaregiverServiceRequestPageResponse list(UUID uid,ServiceRequestStatus status,int page,int size){User caregiver=requireCaregiver(uid);requests.findByCaregiverUserAndStatusOrderByCreatedAtDesc(caregiver,ServiceRequestStatus.PENDENTE).forEach(this::expireIfNeeded);int safePage=Math.max(page,0),safeSize=Math.min(Math.max(size,1),50);PageRequest pageable=PageRequest.of(safePage,safeSize,Sort.by(Sort.Direction.DESC,"createdAt"));Page<ServiceRequest> result=status==null?requests.findByCaregiverUser(caregiver,pageable):requests.findByCaregiverUserAndStatus(caregiver,status,pageable);List<CaregiverReceivedRequestResponse> content=result.getContent().stream().map(e->response(e,hasConflict(e))).toList();return new CaregiverServiceRequestPageResponse(content,result.getNumber(),result.getSize(),result.getTotalElements(),result.getTotalPages(),result.isLast());}
 @Transactional public CaregiverReceivedRequestResponse details(UUID uid,UUID id){ServiceRequest e=owned(uid,id);expireIfNeeded(e);return response(e,hasConflict(e));}
 @Transactional public CaregiverReceivedRequestResponse accept(UUID uid,UUID id){ServiceRequest e=ownedForUpdate(uid,id);requirePending(e);e.setStatus(ServiceRequestStatus.ACEITA);if(contracts.existsByServiceRequestId(e.getId()))throw new BusinessException("Esta solicitação já foi respondida.",HttpStatus.CONFLICT);CareContract c=new CareContract();c.setServiceRequest(e);c.setResponsibleUser(e.getResponsibleUser());c.setCaregiverUser(e.getCaregiverUser());c.setAssistedPerson(e.getAssistedPerson());c.setStartDate(e.getStartDate());c.setEndDate(e.getEndDate());c.setStatus(e.getStartDate().isAfter(LocalDate.now())?CareContractStatus.AGENDADA:CareContractStatus.ATIVA);contracts.save(c);notifications.create(e.getResponsibleUser(),NotificationType.SERVICE_REQUEST_ACCEPTED,"Solicitação aceita","O cuidador aceitou sua solicitação de serviço.",e.getId());return response(e,hasConflict(e));}
 @Transactional public CaregiverReceivedRequestResponse reject(UUID uid,UUID id,String reason){ServiceRequest e=ownedForUpdate(uid,id);requirePending(e);e.setStatus(ServiceRequestStatus.REJEITADA);e.setRejectionReason(reason==null||reason.isBlank()?null:reason.trim());notifications.create(e.getResponsibleUser(),NotificationType.SERVICE_REQUEST_REJECTED,"Solicitação rejeitada","O cuidador rejeitou sua solicitação de serviço.",e.getId());return response(e,hasConflict(e));}
 private ServiceRequest owned(UUID uid,UUID id){User caregiver=requireCaregiver(uid);return requests.findByIdAndCaregiverUser(id,caregiver).orElseThrow(()->new BusinessException("Solicitação não encontrada.",HttpStatus.NOT_FOUND));}private ServiceRequest ownedForUpdate(UUID uid,UUID id){User caregiver=requireCaregiver(uid);return requests.findForUpdateByIdAndCaregiverUser(id,caregiver).orElseThrow(()->new BusinessException("Solicitação não encontrada.",HttpStatus.NOT_FOUND));}private User requireCaregiver(UUID id){User u=users.findById(id);if(u.getUserType()!=UserType.CUIDADOR&&u.getUserType()!=UserType.CAREGIVER)throw new BusinessException("Acesso permitido apenas para cuidadores.",HttpStatus.FORBIDDEN);return u;}private void requirePending(ServiceRequest e){expireIfNeeded(e);if(e.getStatus()!=ServiceRequestStatus.PENDENTE)throw new BusinessException("Esta solicitação já foi respondida.",HttpStatus.CONFLICT);}private void expireIfNeeded(ServiceRequest e){if(e.getStatus()==ServiceRequestStatus.PENDENTE&&e.getExpiresAt().isBefore(Instant.now()))e.setStatus(ServiceRequestStatus.EXPIRADA);}
 private boolean hasConflict(ServiceRequest target){return requests.findByCaregiverUserAndStatusOrderByCreatedAtDesc(target.getCaregiverUser(),ServiceRequestStatus.ACEITA).stream().filter(other->!other.getId().equals(target.getId())).anyMatch(other->dateOverlap(target,other)&&scheduleOverlap(target,other));}private boolean dateOverlap(ServiceRequest a,ServiceRequest b){LocalDate ae=a.getEndDate()==null?LocalDate.MAX:a.getEndDate(),be=b.getEndDate()==null?LocalDate.MAX:b.getEndDate();return !a.getStartDate().isAfter(be)&&!b.getStartDate().isAfter(ae);}private boolean scheduleOverlap(ServiceRequest a,ServiceRequest b){return a.getScheduleDays().stream().anyMatch(x->b.getScheduleDays().stream().anyMatch(y->x.getWeekday()==y.getWeekday()&&x.getStartTime().isBefore(y.getEndTime())&&x.getEndTime().isAfter(y.getStartTime())));}
 private CaregiverReceivedRequestResponse response(ServiceRequest e,boolean conflict){AssistedPerson p=e.getAssistedPerson();AddressFields a=p.getEnderecoCuidado();ResponsibleProfile rp=responsibleProfiles.findByUser(e.getResponsibleUser()).orElse(null);return new CaregiverReceivedRequestResponse(e.getId(),e.getStatus(),e.getCreatedAt(),e.getExpiresAt(),conflict,new CaregiverReceivedRequestResponse.Responsible(e.getResponsibleUser().getId(),e.getResponsibleUser().getFullName(),rp==null?null:String.valueOf(rp.getParentescoOutro()!=null?rp.getParentescoOutro():rp.getParentesco()),rp==null?null:String.valueOf(rp.getPreferenciaContato())),new CaregiverReceivedRequestResponse.Assisted(p.getId(),p.getNome(),Period.between(p.getDataNascimento(),LocalDate.now()).getYears(),p.getGrauDependencia(),p.getMobilidade(),new LinkedHashSet<>(p.getAlergias()),new LinkedHashSet<>(p.getRestricoesAlimentares()),p.getMedicamentos(),p.getObservacoes()),new CaregiverReceivedRequestResponse.CareAddress(a.getCep(),a.getRua(),a.getNumero(),a.getComplemento(),a.getBairro(),a.getCidade(),a.getEstado(),a.getPontoReferencia()),null,e.getHiringType(),e.getStartDate(),e.getEndDate(),new LinkedHashSet<>(e.getSpecificDates()),e.getScheduleDays().stream().map(x->new CaregiverReceivedRequestResponse.Schedule(x.getWeekday(),x.getStartTime(),x.getEndTime())).toList(),e.getNeedsDescription(),new LinkedHashSet<>(e.getActivities()),e.getAdditionalNotes(),e.getNegotiationNotes(),e.getRejectionReason());}}
